```go
// Package rto implements the RFC 6298 retransmission-timer estimator together
// with Karn's algorithm and spurious-timeout (DSACK / Eifel) detection.
//
// The estimator keeps SRTT and RTTVAR using the integer forms of the RFC
// update equations:
//
//	RTTVAR = (3*RTTVAR + |SRTT - R|) / 4
//	SRTT   = (7*SRTT   + R)        / 8
//	RTO    = SRTT + K*RTTVAR,  K = 4
//
// The result is clamped to [1s, 60s].  When the retransmission timer expires
// the RTO is exponentially backed off (doubled) and capped at 60s.
//
// Karn's algorithm: an ACK for a segment that was retransmitted is ambiguous,
// so it must not produce an RTT sample.  Eifel timestamps remove the ambiguity;
// when the ACK echoes the *original* transmission the sample is usable and the
// timeout is proven spurious.
//
// On a spurious classification ("the original data arrived, the retransmission
// was unnecessary") the backoff state is rolled back exactly to the value it
// had immediately before the first timeout that triggered the retransmission.
package rto

import "time"

const (
	// K is the RTO variance multiplier from RFC 6298 section 2.
	K = 4
	// MinRTO is the lower bound applied to every computed RTO (RFC 6298 2.4).
	MinRTO = time.Second
	// MaxRTO is the upper bound for exponential backoff (RFC 6298 2.5 / 5.5).
	MaxRTO = 60 * time.Second
	// InitialRTO is used before the first RTT measurement (RFC 6298 2.1).
	InitialRTO = time.Second
)

// Class is the verdict for a single timer expiration.
type Class int

const (
	// Pending means no DSACK/Eifel evidence has arrived yet.
	Pending Class = iota
	// RealLoss means the retransmitted data was genuinely needed.
	RealLoss
	// Spurious means the original transmission arrived; the timeout was bogus.
	Spurious
)

func (c Class) String() string {
	switch c {
	case RealLoss:
		return "real-loss"
	case Spurious:
		return "spurious"
	default:
		return "pending"
	}
}

// TimeoutRecord captures one retransmission-timer expiration and its verdict.
type TimeoutRecord struct {
	Seq         uint32
	At          time.Duration
	Class       Class
	PrevRTO     time.Duration // RTO immediately before this timeout
	PrevBackoff int           // backoff exponent immediately before this timeout
	rolledBack  bool
}

// AckInfo carries the optional evidence attached to an ACK.
type AckInfo struct {
	// HasRTT reports whether RTT (measured from the echoed transmission) is
	// available for sampling.
	HasRTT bool
	RTT    time.Duration
	// EifelOriginal is true when the ACK's timestamp echo identifies the
	// original (pre-retransmission) transmission.  This proves the timeout
	// spurious and makes the RTT sample unambiguous.
	EifelOriginal bool
}

type segment struct {
	seq           uint32
	retransmitted bool
}

// Machine is the retransmission-timer state machine.
type Machine struct {
	srtt     time.Duration
	rttvar   time.Duration
	haveSRTT bool

	baseRTO time.Duration // estimator output, before backoff
	backoff int           // current backoff exponent
	rto     time.Duration // current effective RTO (baseRTO << backoff, capped)

	outstanding map[uint32]*segment
	timeouts    []TimeoutRecord
	firstTO     map[uint32]int
	lastTO      map[uint32]int
}

// New returns a Machine in its pre-measurement state (RTO = 1s).
func New() *Machine {
	return &Machine{
		baseRTO:     InitialRTO,
		rto:         InitialRTO,
		outstanding: make(map[uint32]*segment),
		firstTO:     make(map[uint32]int),
		lastTO:      make(map[uint32]int),
	}
}

// RTO returns the current effective retransmission timeout.
func (m *Machine) RTO() time.Duration { return m.rto }

// BaseRTO returns the estimator output without exponential backoff.
func (m *Machine) BaseRTO() time.Duration { return m.baseRTO }

// Backoff returns the current backoff exponent.
func (m *Machine) Backoff() int { return m.backoff }

// SRTT returns the smoothed RTT and whether a measurement exists.
func (m *Machine) SRTT() (time.Duration, bool) { return m.srtt, m.haveSRTT }

// RTTVAR returns the RTT variance and whether a measurement exists.
func (m *Machine) RTTVAR() (time.Duration, bool) { return m.rttvar, m.haveSRTT }

// Timeouts returns the ordered per-expiration classification vector.
func (m *Machine) Timeouts() []TimeoutRecord {
	out := make([]TimeoutRecord, len(m.timeouts))
	copy(out, m.timeouts)
	return out
}

// OnSend records a segment leaving the sender.
func (m *Machine) OnSend(seq uint32, at time.Duration) {
	if _, ok := m.outstanding[seq]; ok {
		return
	}
	m.outstanding[seq] = &segment{seq: seq}
}

// OnTimeout records a timer expiration for seq, applies exponential backoff and
// marks the segment retransmitted.  The pre-timeout state is retained so that a
// later spurious verdict can roll it back exactly.
func (m *Machine) OnTimeout(seq uint32, at time.Duration) {
	seg, ok := m.outstanding[seq]
	if !ok {
		seg = &segment{seq: seq}
		m.outstanding[seq] = seg
	}
	idx := len(m.timeouts)
	m.timeouts = append(m.timeouts, TimeoutRecord{
		Seq:         seq,
		At:          at,
		Class:       Pending,
		PrevRTO:     m.rto,
		PrevBackoff: m.backoff,
	})
	if _, ok := m.firstTO[seq]; !ok {
		m.firstTO[seq] = idx
	}
	m.lastTO[seq] = idx

	m.backoff++
	m.rto = m.rtoForBackoff(m.backoff)
	seg.retransmitted = true
}

// OnAck consumes an ACK for seq.
//
//   - If the segment was retransmitted and Eifel evidence does not identify the
//     original transmission, the ACK is ambiguous: no RTT sample is taken
//     (Karn) and the timeout is classified as real loss.
//   - If Eifel evidence identifies the original transmission, the timeout was
//     spurious: backoff is rolled back and the (unambiguous) sample is used.
//   - If the segment was never retransmitted the RTT sample is always used.
func (m *Machine) OnAck(seq uint32, at time.Duration, info AckInfo) {
	seg, ok := m.outstanding[seq]
	if !ok {
		return
	}
	if seg.retransmitted {
		if info.EifelOriginal {
			m.classify(seq, Spurious)
			m.rollback(seq)
		} else {
			m.classify(seq, RealLoss)
		}
	}
	// Karn: never sample an ambiguous retransmitted segment.  Eifel removes the
	// ambiguity, so that sample is allowed.
	if info.HasRTT && (!seg.retransmitted || info.EifelOriginal) {
		m.updateRTT(info.RTT)
	}
	delete(m.outstanding, seq)
}

// OnDSACK consumes a duplicate-SACK proving that the original data for seq had
// already arrived.  Every timeout for seq is reclassified spurious and the
// backoff state is rolled back to its pre-first-timeout value.
func (m *Machine) OnDSACK(seq uint32, at time.Duration) {
	m.classify(seq, Spurious)
	m.rollback(seq)
	delete(m.outstanding, seq)
}

// ---------------------------------------------------------------------------
// internals
// ---------------------------------------------------------------------------

func (m *Machine) updateRTT(r time.Duration) {
	if r < 0 {
		return
	}
	if !m.haveSRTT {
		m.srtt = r
		m.rttvar = r / 2
		m.haveSRTT = true
	} else {
		diff := m.srtt - r
		if diff < 0 {
			diff = -diff
		}
		m.rttvar = (3*m.rttvar + diff) / 4
		m.srtt = (7*m.srtt + r) / 8
	}
	m.baseRTO = m.computeBase()
	m.backoff = 0
	m.rto = m.baseRTO
}

func (m *Machine) computeBase() time.Duration {
	if !m.haveSRTT {
		return InitialRTO
	}
	rto := m.srtt + K*m.rttvar
	if rto < MinRTO {
		rto = MinRTO
	}
	if rto > MaxRTO {
		rto = MaxRTO
	}
	return rto
}

func (m *Machine) rtoForBackoff(b int) time.Duration {
	rto := m.baseRTO
	for i := 0; i < b; i++ {
		if rto >= MaxRTO/2 {
			return MaxRTO
		}
		rto *= 2
	}
	if rto > MaxRTO {
		rto = MaxRTO
	}
	return rto
}

// classify updates the verdict for every timeout of seq.  A spurious verdict
// overrides a previously recorded real-loss verdict; a real-loss verdict only
// fills in still-pending records.
func (m *Machine) classify(seq uint32, c Class) {
	for i := range m.timeouts {
		if m.timeouts[i].Seq != seq {
			continue
		}
		if c == Spurious || m.timeouts[i].Class == Pending {
			m.timeouts[i].Class = c
		}
	}
}

// rollback restores the backoff state captured before the first timeout of seq.
func (m *Machine) rollback(seq uint32) {
	idx, ok := m.firstTO[seq]
	if !ok {
		return
	}
	rec := &m.timeouts[idx]
	if rec.rolledBack {
		return
	}
	m.backoff = rec.PrevBackoff
	m.rto = rec.PrevRTO
	rec.rolledBack = true
}
