### `rto_test.go`

```go
package rto

import (
	"testing"
	"time"
)

type opKind int

const (
	opSend opKind = iota
	opAck
	opTimeout
	opDSACK
)

type step struct {
	op    opKind
	seq   uint32
	at    time.Duration
	rtt   time.Duration
	eifel bool
}

type testCase struct {
	name        string
	trace       []step
	wantSRTT    time.Duration
	wantRTTVAR  time.Duration
	wantRTO     time.Duration
	wantBackoff int
	wantClasses []Class
}

func runTrace(tc testCase) *Machine {
	m := New()
	for _, s := range tc.trace {
		switch s.op {
		case opSend:
			m.OnSend(s.seq, s.at)
		case opAck:
			m.OnAck(s.seq, s.at, AckInfo{
				HasRTT:        s.rtt > 0,
				RTT:           s.rtt,
				EifelOriginal: s.eifel,
			})
		case opTimeout:
			m.OnTimeout(s.seq, s.at)
		case opDSACK:
			m.OnDSACK(s.seq, s.at)
		}
	}
	return m
}

func TestRetransmissionTimer(t *testing.T) {
	ms := func(v int64) time.Duration { return time.Duration(v) * time.Millisecond }
	s := func(v int64) time.Duration { return time.Duration(v) * time.Second }

	cases := []testCase{
		{
			// A DSACK proves the first timeout was spurious (roll back to the
			// 1s pre-timeout RTO), then a genuine retransmission is later ACKed
			// and Karn suppresses the ambiguous RTT sample.
			name: "dsack_spurious_then_karn_real",
			trace: []step{
				{op: opSend, seq: 1, at: 0},
				{op: opAck, seq: 1, at: ms(200), rtt: ms(200)},
				{op: opSend, seq: 2, at: ms(250)},
				{op: opTimeout, seq: 2, at: ms(1250)},
				{op: opDSACK, seq: 2, at: ms(1300)},
				{op: opSend, seq: 3, at: ms(1400)},
				{op: opTimeout, seq: 3, at: ms(2400)},
				{op: opAck, seq: 3, at: ms(2600), rtt: ms(200)},
			},
			wantSRTT:    ms(200),
			wantRTTVAR:  ms(100),
			wantRTO:     s(2),
			wantBackoff: 1,
			wantClasses: []Class{Spurious, RealLoss},
		},
		{
			// Eifel timestamp identifies the original transmission: the timeout
			// is spurious and the backoff state returns exactly to 1s / 0.
			name: "eifel_spurious_rolls_back_backoff",
			trace: []step{
				{op: opSend, seq: 1, at: 0},
				{op: opAck, seq: 1, at: ms(200), rtt: ms(200)},
				{op: opSend, seq: 2, at: ms(250)},
				{op: opTimeout, seq: 2, at: ms(1250)},
				{op: opAck, seq: 2, at: ms(1300), eifel: true},
			},
			wantSRTT:    ms(200),
			wantRTTVAR:  ms(100),
			wantRTO:     s(1),
			wantBackoff: 0,
			wantClasses: []Class{Spurious},
		},
		{
			// Exponential backoff is capped at 60s.
			name: "backoff_cap_at_60s",
			trace: []step{
				{op: opSend, seq: 1, at: 0},
				{op: opAck, seq: 1, at: ms(200), rtt: ms(200)},
				{op: opSend, seq: 2, at: ms(250)},
				{op: opTimeout, seq: 2, at: ms(300)},
				{op: opTimeout, seq: 2, at: ms(400)},
				{op: opTimeout, seq: 2, at: ms(500)},
				{op: opTimeout, seq: 2, at: ms(600)},
				{op: opTimeout, seq: 2, at: ms(700)},
				{op: opTimeout, seq: 2, at: ms(800)},
			},
			wantSRTT:    ms(200),
			wantRTTVAR:  ms(100),
			wantRTO:     s(60),
			wantBackoff: 6,
			wantClasses: []Class{Pending, Pending, Pending, Pending, Pending, Pending},
		},
		{
			// Several backoffs accumulate, then DSACK rolls the whole chain back
			// to the state before the first timeout (1s / exponent 0).
			name: "dsack_after_multi_backoff_restores_first_pre_timeout",
			trace: []step{
				{op: opSend, seq: 1, at: 0},
				{op: opAck, seq: 1, at: ms(200), rtt: ms(200)},
				{op: opSend, seq: 2, at: ms(250)},
				{op: opTimeout, seq: 2, at: ms(300)},
				{op: opTimeout, seq: 2, at: ms(400)},
				{op: opTimeout, seq: 2, at: ms(500)},
				{op: opDSACK, seq: 2, at: ms(600)},
			},
			wantSRTT:    ms(200),
			wantRTTVAR:  ms(100),
			wantRTO:     s(1),
			wantBackoff: 0,
			wantClasses: []Class{Spurious, Spurious, Spurious},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m := runTrace(tc)

			if got, _ := m.SRTT(); got != tc.wantSRTT {
				t.Errorf("SRTT = %v, want %v", got, tc.wantSRTT)
			}
			if got, _ := m.RTTVAR(); got != tc.wantRTTVAR {
				t.Errorf("RTTVAR = %v, want %v", got, tc.wantRTTVAR)
			}
			if got := m.RTO(); got != tc.wantRTO {
				t.Errorf("RTO = %v, want %v", got, tc.wantRTO)
			}
			if got := m.Backoff(); got != tc.wantBackoff {
				t.Errorf("backoff = %d, want %d", got, tc.wantBackoff)
			}

			recs := m.Timeouts()
			if len(recs) != len(tc.wantClasses) {
				t.Fatalf("got %d timeout records, want %d", len(recs), len(tc.wantClasses))
			}
			for i, want := range tc.wantClasses {
				if recs[i].Class != want {
					t.Errorf("timeout[%d] class = %v, want %v", i, recs[i].Class, want)
				}
			}
		})
	}
}

func TestFirstMeasurement(t *testing.T) {
	m := New()
	if m.RTO() != InitialRTO {
		t.Fatalf("initial RTO = %v, want %v", m.RTO(), InitialRTO)
	}
	m.OnSend(1, 0)
	m.OnAck(1, 200*time.Millisecond, AckInfo{HasRTT: true, RTT: 200 * time.Millisecond})
	srtt, ok := m.SRTT()
	if !ok || srtt != 200*time.Millisecond {
		t.Fatalf("SRTT = %v (ok=%v), want 200ms", srtt, ok)
	}
	rttvar, _ := m.RTTVAR()
	if rttvar != 100*time.Millisecond {
		t.Fatalf("RTTVAR = %v, want 100ms", rttvar)
	}
	// SRTT + 4*RTTVAR = 600ms, clamped up to the 1s floor.
	if m.RTO() != time.Second {
		t.Fatalf("RTO = %v, want 1s", m.RTO())
	}
}

func TestKarnSuppressesSample(t *testing.T) {
	m := New()
	m.OnSend(1, 0)
	m.OnAck(1, 100*time.Millisecond, AckInfo{HasRTT: true, RTT: 100 * time.Millisecond})
	m.OnSend(2, 150*time.Millisecond)
	m.OnTimeout(2, 1150*time.Millisecond)
	// Ambiguous ACK with a tempting RTT sample: must be ignored.
	m.OnAck(2, 1300*time.Millisecond, AckInfo{HasRTT: true, RTT: 1150 * time.Millisecond})

	srtt, _ := m.SRTT()
	if srtt != 100*time.Millisecond {
		t.Fatalf("SRTT = %v, want unchanged 100ms (Karn)", srtt)
	}
	if m.Backoff() != 1 {
		t.Fatalf("backoff = %d, want 1 (real loss keeps backoff)", m.Backoff())
	}
}
